-- Stock ChickNSter : coûts HT et composants des burgers et menus (fichier Food cost, novembre 2026).
-- À coller dans Supabase > SQL Editor du projet « CNS Stock », puis « Run ». Peut être relancé sans risque.

begin;

-- 1. Produits : crée les nouveaux, met à jour coût, famille et unité des existants.
--    Les seuils, colisages et fournisseurs déjà saisis sont conservés.
insert into public.stock_docs (col, id, data)
select 'products', v.id, v.data from (values
  ('poulet','{"name": "Pièce de poulet", "family": "Poulet", "unit": "pièce", "cost": 10.5, "pack": null, "supplier": "", "minR": null, "tgtR": null, "minD": null, "tgtD": null}'::jsonb),
