insert into public.stock_docs (col, id, data)
select 'menu', 'fc-' || md5(lower(trim(v.name))), jsonb_build_object('name', v.name) || v.patch from v
where not exists (select 1 from public.stock_docs d where d.col = 'menu' and lower(trim(d.data->>'name')) = lower(trim(v.name)));

commit;

-- Vérification : coût matière calculé de chaque recette.
select d.data->>'name' as article,
  round(sum((c->>'qty')::numeric * (p.data->>'cost')::numeric), 2) as cout_ht
from public.stock_docs d
cross join jsonb_array_elements(d.data->'components') c
join public.stock_docs p on p.col = 'products' and p.id = c->>'pid'
where d.col = 'menu' and coalesce((d.data->>'skip')::boolean, false) = false
group by 1 order by 1;
